/** Shared guards of suspend and reinstate; returns the live target member. */
async function loadSuspensionTarget(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (
    member.userId === actor.userId ||
    !hasRoleAtLeast(actor.role, member.role)
  ) {
    throw new PermissionDeniedError("member:remove", {
      allowed: false,
      action: "member:remove",
      resourceKind: "member",
      reason: "denied_by_role",
    });
  }
  return member;
}

export async function suspendMember(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

export async function reinstateMember(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status !== "suspended") return member;

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}
